<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/universal-header.php';
require_once __DIR__.'/includes/member-layout.php';
require_once __DIR__.'/includes/creator-club-view.php';
$viewer=az_require_auth();
$memberships=az_creator_club_my_memberships($viewer);
$following=count(array_filter($memberships,static fn(array $row):bool=>(bool)$row['following']));
$view=az_creator_club_request_value('view')==='unread'?'unread':'all';
$creatorFilter=filter_var(az_creator_club_request_value('creator'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$cursor=az_creator_club_request_value('cursor');
$pageError='';
try{$feed=az_creator_club_feed_page($viewer,['creator'=>$creatorFilter,'view'=>$view,'cursor'=>$cursor,'limit'=>12]);}
catch(AzHttpError $e){$pageError=$e->getMessage();$feed=['posts'=>[],'nextCursor'=>null,'unreadCount'=>0];}
$creatorOptions=[];
foreach($memberships as $membership){
    $id=(int)$membership['creator_id'];$target=az_account_user($id);
    if(!empty($membership['available'])&&$target&&$target['status']==='active'&&az_social_visible(az_social_row($id),$viewer,$target))$creatorOptions[$id]=az_social_name($target);
}
$statusLabels=['active_test'=>'Active test access','expired'=>'Expired','revoked'=>'Revoked','scheduled'=>'Scheduled test access','disabled'=>'Test access disabled','test_disabled'=>'Test access disabled','unavailable'=>'Unavailable'];
az_creator_club_page_start('My Clubs','creator-club-workspace',$viewer);
az_creator_club_navigation('mine',$viewer);
?>
<header class="club-hero club-hero-feed"><div class="club-hero-heading"><div><p class="club-eyebrow">A LITTLE CLOSER TO YOUR CREATORS</p><h1>My Clubs<span>.</span></h1><p>Your creators, together in one feed. Pick up where you left off and make room for something new.</p></div><a class="club-secondary" href="creator-clubs.php">Explore creators <span aria-hidden="true">↗</span></a></div><div class="club-stat-grid"><div><strong><?= $following ?></strong><span>Clubs followed</span></div><div><strong><?= (int)$feed['unreadCount'] ?></strong><span><?= $creatorFilter?'Unread in this club':'Unread updates' ?></span></div><div><a href="#club-memberships" class="club-stat-link">Your preferences <span aria-hidden="true">↓</span></a><span>Follows, notifications &amp; access</span></div></div></header>
