<div class="club-feed-controls"><nav class="club-filter-tabs" aria-label="Feed view"><a href="<?= az_h(az_creator_club_link('creator-club-workspace.php',['view'=>'all','creator'=>$creatorFilter?:null],'club-updates')) ?>"<?= $view==='all'?' aria-current="page"':'' ?>>All updates</a><a aria-label="Unread" href="<?= az_h(az_creator_club_link('creator-club-workspace.php',['view'=>'unread','creator'=>$creatorFilter?:null],'club-updates')) ?>"<?= $view==='unread'?' aria-current="page"':'' ?>>Unread <span class="club-count"><?= (int)$feed['unreadCount'] ?></span></a></nav><form class="club-creator-filter" action="creator-club-workspace.php#club-updates" method="get"><input type="hidden" name="view" value="<?= az_h($view) ?>"><label for="club-feed-creator">Filter by creator</label><div><select id="club-feed-creator" name="creator"><option value="">All my creators</option><?php foreach($creatorOptions as $id=>$creatorName): ?><option value="<?= $id ?>"<?= $creatorFilter===$id?' selected':'' ?>><?= az_h($creatorName) ?></option><?php endforeach; ?><?php if($creatorFilter&&!isset($creatorOptions[$creatorFilter])): ?><option value="<?= $creatorFilter ?>" selected>Selected creator is unavailable</option><?php endif; ?></select><button type="submit" class="club-secondary">Apply filter</button></div></form></div>
<p class="club-help club-read-help">You choose what is read. Read status is saved to your account; opening a post or a notification does not change it.</p>
<?php if($pageError): ?><p class="club-notice" role="alert"><?= az_h($pageError) ?> <a href="<?= az_h(az_creator_club_link('creator-club-workspace.php',['view'=>$view,'creator'=>$creatorFilter?:null],'club-updates')) ?>">Return to the latest updates</a></p><?php elseif($cursor!==''): ?><p class="club-page-context">Showing older updates <a href="<?= az_h(az_creator_club_link('creator-club-workspace.php',['view'=>$view,'creator'=>$creatorFilter?:null],'club-updates')) ?>">Back to latest</a></p><?php endif; ?>
<?php if(!$feed['posts']&&!$pageError): ?><div class="club-empty club-empty-centered"><span class="club-empty-symbol" aria-hidden="true"><?= $view==='unread'?'✓':'♡' ?></span><h3><?= $view==='unread'?'You’re all caught up':($following?'Your next update is on its way':'Make yourself at home') ?></h3><p><?= $view==='unread'?'There are no unread updates for this view. You can mark any available update unread whenever you want.':($following?'Published updates you can access will appear here. Try another creator or check back soon.':'Follow a creator to bring their free updates into your feed.') ?></p><a class="club-secondary" href="<?= $view==='unread'?az_h(az_creator_club_link('creator-club-workspace.php',['view'=>'all','creator'=>$creatorFilter?:null],'club-updates')):'creator-clubs.php' ?>"><?= $view==='unread'?'View all updates':'Explore creators' ?></a></div><?php endif; ?>
<div class="club-feed-list">
