feedCreator" value="<?= $creatorFilter ?>"><input type="hidden" name="feedView" value="<?= az_h($view) ?>"><input type="hidden" name="feedCursor" value="<?= az_h($cursor) ?>"><button type="submit" class="club-read-button"><?= $isRead?'Mark unread':'Mark read' ?></button></form></footer></article><?php endforeach; ?>
</div>
<?php if(!empty($feed['nextCursor'])): ?><div class="club-pagination"><a class="club-secondary" rel="next" href="<?= az_h(az_creator_club_link('creator-club-workspace.php',['view'=>$view,'creator'=>$creatorFilter?:null,'cursor'=>$feed['nextCursor']],'club-updates')) ?>">Load older updates <span aria-hidden="true">↓</span></a><p>Your read choices stay with your account.</p></div><?php endif; ?>
</section>
<section class="club-section" id="club-memberships"><header><div><p class="club-eyebrow">YOUR CONNECTIONS</p><h2>Manage follows &amp; access</h2></div><a class="club-text-link" href="creator-clubs.php">Explore creators ↗</a></header>
<?php if(!$memberships): ?><div class="club-empty club-empty-centered"><span class="club-empty-symbol" aria-hidden="true">♡</span><h3>Make yourself at home</h3><p>Follow a creator to find their club here. You control which clubs send updates to your notification bell.</p><a class="club-primary" href="creator-clubs.php">Find a creator</a></div><?php endif; ?>
<div class="club-memberships">
